@import "../pantoken-icons.less";        // Only icons/logos
@import "../pantoken-logos.less";
// No token imports!
```

## Fix Strategy

### Option A: Create Content Token Variables (Recommended)

Add a separate constant for content-specific token mappings:

**[renderers/tinymce/scripts/generate.ts]** Add after LESS_TOKEN_VARIABLES:
```typescript
const LESS_CONTENT_TOKEN_VARIABLES = [
  ["background-color", "--instui-color-background-container"],  // Container for editing area
  ["text-color", "--instui-color-text-base"],
  ["text-color-muted", "--instui-color-text-muted"],
  ["border-color", "--instui-color-stroke-base"],
  ["border-color-light", "--instui-color-stroke-base"],
  // ... copy relevant tokens, adjusting semantic mapping as needed
] as const;

function writeContentTokenVariables(name: string, theme: ThemeName, mode: "light" | "dark"): void {
  const resolved = new Map(resolveTokens(themes[theme], { mode }));
  const lines = LESS_CONTENT_TOKEN_VARIABLES.map(([lessName, tokenName]) => {
    const value = resolved.get(tokenName);
    if (!value) throw new Error(`Missing ${tokenName} in ${theme} ${mode} content tokens for ${name}`);
