  mkdirSync(generatedLessRoot, { recursive: true });
  writeFileSync(
    resolve(generatedLessRoot, `${name}-content-tokens.less`),
    `${lines.join("\n")}\n`
  );
}
```

Then in `generate()`:
```typescript
