  ```typescript
  const localFontsCss = fontsCss.replace(
    /\.\.\/assets\/fonts\/([^"\s)]+\.woff2)/gu, 
    (_, path: string) => fontAssetUrls[`/node_modules/@pantoken/components/assets/fonts/${path}`]
